import 'package:flutter/material.dart';void main() {  runApp(const MyApp());}class MyApp extends StatelessWidget {  const MyApp({Key? key}) : super(key: key);  @override  Widget build(BuildContext context) {    return const MaterialApp(      title: 'Simple Calculator',      home: Calculator(),    );  }}class Calculator extends StatefulWidget {  const Calculator({Key? key}) : super(key: key);  @override  State<Calculator> createState() => _CalculatorState();}class _CalculatorState extends State<Calculator> {  String _expression = '';  String _result = '';  void _onPressed(String value) {    setState(() {      if (value == 'C') {        _expression = '';        _result = '';      } else if (value == '=') {        try {          _result = _calculate(_expression).toString();        } catch (e) {          _result = 'Error';        }      } else {        _expression += value;      }    });  }  double _calculate(String expression) {    // Simple calculator logic    // This is a very basic implementation and does not handle all cases    if (expression.contains('+')) {      final parts = expression.split('+');      return double.parse(parts[0]) + double.parse(parts[1]);    } else if (expression.contains('-')) {      final parts = expression.split('-');      return double.parse(parts[0]) - double.parse(parts[1]);    } else if (expression.contains('*')) {      final parts = expression.split('*');      return double.parse(parts[0]) * double.parse(parts[1]);    } else if (expression.contains('/')) {      final parts = expression.split('/');      return double.parse(parts[0]) / double.parse(parts[1]);    } else {      return double.parse(expression);    }  }  @override  Widget build(BuildContext context) {    return Scaffold(      body: Column(        mainAxisAlignment: MainAxisAlignment.spaceBetween,        children: [          Container(            padding: const EdgeInsets.all(20),            child: Column(              children: [                Text(                  _expression,                  style: const TextStyle(fontSize: 24),                ),                Text(                  _result,                  style: const TextStyle(fontSize: 48),                ),              ],            ),          ),          Container(            padding: const EdgeInsets.all(20),            child: Column(              children: [                Row(                  mainAxisAlignment: MainAxisAlignment.spaceBetween,                  children: [                    ElevatedButton(                      onPressed: () => _onPressed('7'),                      child: const Text('7'),                    ),                    ElevatedButton(                      onPressed: () => _onPressed('8'),                      child: const Text('8'),                    ),                    ElevatedButton(                      onPressed: () => _onPressed('9'),                      child: const Text('9'),                    ),                    ElevatedButton(                      onPressed: () => _onPressed('/'),                      child: const Text('/'),                    ),                  ],                ),                Row(                  mainAxisAlignment: MainAxisAlignment.spaceBetween,                  children: [                    ElevatedButton(                      onPressed: () => _onPressed('4'),                      child: const Text('4'),                    ),                    ElevatedButton(                      onPressed: () => _onPressed('5'),                      child: const Text('5'),                    ),                    ElevatedButton(                      onPressed: () => _onPressed('6'),                      child: const Text('6'),                    ),                    ElevatedButton(                      onPressed: () => _onPressed('*'),                      child: const Text('*'),                    ),                  ],                ),                Row(                  mainAxisAlignment: MainAxisAlignment.spaceBetween,                  children: [                    ElevatedButton(                      onPressed: () => _onPressed('1'),                      child: const Text('1'),                    ),                    ElevatedButton(                      onPressed: () => _onPressed('2'),                      child: const Text('2'),                    ),                    ElevatedButton(                      onPressed: () => _onPressed('3'),                      child: const Text('3'),                    ),                    ElevatedButton(                      onPressed: () => _onPressed('-'),                      child: const Text('-'),                    ),                  ],                ),                Row(                  mainAxisAlignment: MainAxisAlignment.spaceBetween,                  children: [                    ElevatedButton(                      onPressed: () => _onPressed('0'),                      child: const Text('0'),                    ),                    ElevatedButton(                      onPressed: () => _onPressed('.'),                      child: const Text('.'),                    ),                    ElevatedButton(                      onPressed: () => _onPressed('C'),                      child: const Text('C'),                    ),                    ElevatedButton(                      onPressed: () => _onPressed('+'),                      child: const Text('+'),                    ),                  ],                ),                Row(                  mainAxisAlignment: MainAxisAlignment.spaceBetween,                  children: [                    ElevatedButton(                      onPressed: () => _onPressed('='),                      child: const Text('='),                    ),                  ],                ),              ],            ),          ),        ],      ),    );  }}